presetParts.perFrame:
dec_f = exp (-5/fps);
dec_med = exp (-3/fps);
dec_slow = exp (-.5/fps);

beat = bass + mid + treb; 
avg = avg*dec_slow + beat*(1-dec_slow);
is_beat = above(beat, 1*avg+peak) * above (time, t0+1);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_med;
index = (index + is_beat) %16;
index2 = (index2 + is_beat*bnot(index))%4;

trig =  is_beat*equal(index%2,0);
p1 =  trig*(p1+1) + (1-trig)*p1;
p2 = dec_slow * p2+ (1-dec_slow)*p1;
rott = p2 * 3.1416/4;
q1 = cos(rott);
q2 = sin(rott);


dec_slow= 0;
dir2 = 2*(rand(100)/100-.5);
dir = if(trig*above(abs(dir-dir2),.5),dir2,dir);
dir_ = dir_*dec_slow + (1-dec_slow)*dir;
dir__ = dir__*dec_slow + (1-dec_slow)*dir_;
q3 = dir__;


//Variations
q30 = sin(time/3)*.2;

