sampler sampler_pw_noise_lq;
float w,z,mask,wmask,clouds,fmask,smask,hill1,hill2,fog,forest,sun,dist;
float2 rs0, rs, uv0, uv1, uv2, uv3, uv4, uv5, uv_wat, uv_stars;
float3 water, noise, sky1;
static float speed = 1.4;
static float2 planpos = _qf.xy;
static float2 sunpos = _qf.zw;
static float3 suncol = _qe.rgb;
static float3 skycol = float3 (.6,.8,1)/2;

shader_body {
uv0 = uv;
float2 center = float2 (.5+.5*q3,.5); 
uv1 = (uv-center)*aspect.xy;
wmask = saturate(128*uv1.y);
dist = .5/(uv1.y);
rs0.x = uv1.x * dist; rs0.y = dist ;

rs    = float2 (rs0.x, rs0.y+time*speed)*wmask;
water = tex2D(sampler_noise_hq,rs) + tex2D(sampler_noise_hq,rs/3);
water -= 1.1;
uv_wat   = float2(uv1.x, abs(uv1.y))-water*.1* wmask/dist;
uv_stars = float2(uv1.x, abs(uv1.y))-water*.01* wmask;

sky1 = lerp(q13*exp(-q14*abs(uv1.y)), .5-uv1.y,q15)*skycol;
sun = (.02/length(uv_wat-sunpos));

//hills
hill1 = q31*saturate(16+16*tex2D(sampler_noise_mq,uv_wat.x*q10/2048+rand_preset.x)
           -q10*abs(uv_wat.y));

//stars
uv2 = 64*uv_stars;
smask = (tex2D (sampler_pw_noise_lq,uv2/256 )).b-.8 ;
float stars = saturate(.2/length(abs(frac(uv2)-.5))*smask)*(1-smask*8);
stars *= stars*q26;

//----------------Planet1----------------
float2 rsk = (uv_stars - planpos) ;
float2 dz1 = normalize(rsk);
float rad3 = q12*length (rsk);
float2 uv4 =  tan(rad3)*dz1;
float2 noise = abs(tex2D (sampler_noise_hq,uv4/2)-.5);
float mask3 = saturate(100-71*rad3);
float2 Planet = (uv4*(1+noise.x))*mask3;
float2 pdist = sunpos-planpos;
float pla = saturate(-.2+(dot(Planet,pdist)))/length(pdist)/2;

//forest
z = q11/uv_wat.x ;
uv2.x = abs(z)/2+sign(z)+time*.04*speed ;
float size = (tex2D (sampler_noise_hq,uv2.x/18)+.1);
uv2.y = (uv_wat.y*z/size-.5);
fmask = (uv2.y <= 0) * (uv2.y >= -1);
forest = saturate(GetPixel(uv2*fmask)/abs(z)*2).g*fmask;

uv2.x = abs(z)/2+sign(z)+time*.035*speed ;; 
//size = (tex2D (sampler_noise_hq,uv2.x/28)+.1);
uv2.x = abs(z)/2+sign(z)+time*.035*speed ;; 
uv2.y = (uv_wat.y*z/size-.5);
fmask = (uv2.y <= 0) * (uv2.y >= -1);
forest += saturate(GetPixel(uv2*fmask)/abs(z)*2).g*fmask*.7;

fmask = saturate(1-forest*1.5); 

ret = stars*saturate(1-4*sun)+pow(sun,1)*suncol;
ret *= 1-mask3;
ret += pla*(suncol+skycol)/2;
ret *= 1-hill1;


uv2 = float2(uv_wat.x*2-.5,uv_wat.y*4-.5);
float city  = GetPixel(uv2).r;
ret+= city*hill1*float3 (1,.8,.5);

ret += saturate(sky1)*skycol;
ret *= fmask;

uv2 = float2(.5+uv1.x*.1,uv1.y*.75+.5);
fog = (GetBlur2(frac(uv2)).b)*q25;
ret = ret*saturate(1-fog) + fog*(1+suncol);


rs    = float2 (rs0.x, rs0.y+time*speed*.8+q30*sin(rs0.x*4))*wmask;
water = tex2D(sampler_noise_hq,rs) + tex2D(sampler_noise_hq,rs/4)-1;
float ice = saturate(water.g*1 );
ret += ice*wmask*saturate(sun*2)*4/dist*q20;

ret = 1-exp(-ret*2+.1);


//ret = GetPixel(uv).g;




}
